SELECT     concat(abs(LPAD(CAST(SUBSTR(CAST(t1.tjzq AS STRING), 5, 2) AS INT), 2, '0')), '月') AS month,     ROUND(CAST(t1.year_lend AS DECIMAL(38, 2)) / 100000000, 2) AS bnhsje,     ROUND(CAST(COALESCE(t2.year_lend, 0) AS DECIMAL(38, 2)) / 100000000, 2) AS snhsje FROM     (SELECT         tjzq,         SUM(dyhsbj) AS year_lend      FROM dws_bus_ln_rec_mfm      WHERE SUBSTR(CAST(tjzq AS STRING), 1, 4) = CAST(#{ssnd} AS STRING)      GROUP BY tjzq) t1 LEFT JOIN     (SELECT         tjzq,         SUM(dyhsbj) AS year_lend      FROM dws_bus_ln_rec_mfm      WHERE SUBSTR(CAST(tjzq AS STRING), 1, 4) = CAST(#{ssnd} - 1 AS STRING)      GROUP BY tjzq) t2 ON SUBSTR(CAST(t1.tjzq AS STRING), 5, 2) = SUBSTR(CAST(t2.tjzq AS STRING), 5, 2) ORDER BY CAST(SUBSTR(CAST(t1.tjzq AS STRING), 5, 2) AS INT) 
